/// <reference types="vite/client" />

/** Version and git commit of this bundle — generated by the build-info
 * plugin in vite.config.ts, in release builds and on the dev server alike. */
declare module "virtual:build-info" {
  const buildInfo: {
    /** package.json version. */
    version: string;
    /** Short commit hash, or "unknown" outside a git checkout. */
    commit: string;
    /** The working tree had uncommitted changes. */
    dirty: boolean;
    /** True when served by `npm run dev`, false in a release build. */
    dev: boolean;
  };
  export default buildInfo;
}
